const input = $json.body ?? $json;
const classification = String(input.classification ?? input.seller_response_classification ?? '').toLowerCase();
const decision = String(input.decision ?? '').toLowerCase();
const counteroffer = Number(input.counteroffer_amount ?? input.counteroffer ?? input.accepted_price);
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const lastOffer = Number(input.last_offer_price ?? input.offer_price);
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const identityOk = Boolean(dealId && leadId && propertyId);
const price = Number.isFinite(counteroffer) ? counteroffer : Number.isFinite(lastOffer) ? lastOffer : null;
const withinMao = Number.isFinite(price) && Number.isFinite(dynamicMao) && price <= dynamicMao;
const nearMao = Number.isFinite(price) && Number.isFinite(dynamicMao) && price > dynamicMao && price <= dynamicMao * 1.05;
const materiallyAbove = Number.isFinite(price) && Number.isFinite(dynamicMao) && price > dynamicMao * 1.05;

let action = 'needs_review';
let status = 'needs_review';
let nextWorkflow = 'WF-126';
let humanReview = true;
let contractPrice = price;

if (!identityOk || blockers.length) {
  status = 'blocked';
  action = 'human_review';
} else if ((classification === 'accepted' || decision === 'acceptance_ready') && withinMao) {
  action = 'contract_decision_ready';
  status = 'contract_ready';
  nextWorkflow = 'WF-268';
  humanReview = true;
} else if (classification === 'counteroffer' && withinMao) {
  action = 'accept_counteroffer_or_revise';
  status = 'counteroffer_acceptable';
  nextWorkflow = 'WF-268';
  humanReview = true;
} else if (classification === 'counteroffer' && nearMao) {
  action = 'revised_offer_or_walk_away';
  status = 'counteroffer_near_mao';
  nextWorkflow = 'WF-268';
  humanReview = true;
} else if (classification === 'counteroffer' && materiallyAbove) {
  action = 'walk_away_or_reengage';
  status = 'counteroffer_above_mao';
  nextWorkflow = 'WF-261';
  humanReview = true;
} else {
  action = 'reassess_negotiation';
  status = 'needs_review';
  nextWorkflow = 'WF-126';
}

const guardrail = {
  dynamic_mao_protected: true,
  contract_price: Number.isFinite(contractPrice) ? contractPrice : null,
  dynamic_mao: Number.isFinite(dynamicMao) ? dynamicMao : null,
  within_mao: withinMao,
  near_mao: nearMao,
  materially_above_mao: materiallyAbove
};

return [{ json: {
  ...input,
  workflow_id: 'WF-267',
  workflow_name: 'Acceptable Counteroffer / Acceptance → Revised Offer or Contract Decision Controller',
  action,
  status,
  next_workflow: nextWorkflow,
  human_review_required: humanReview,
  guardrail,
  contract_decision: {
    ready: status === 'contract_ready',
    contract_price: Number.isFinite(contractPrice) ? contractPrice : null,
    seller_response_classification: classification,
    recommendation: action
  },
  identity_valid: identityOk,
  blockers,
  crm_activity: {
    activity_type: 'counteroffer_contract_decision',
    workflow_id: 'WF-267',
    action,
    status,
    next_workflow: nextWorkflow,
    human_review_required: humanReview,
    guardrail
  }
} }];
